#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int data; struct Node *next; } Node;
int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 3; i++) {
        Node *n = malloc(sizeof *n);
        if (!n) return 1;
        n->data = i * 10; n->next = head; head = n;
    }
    for (Node *p = head; p; p = p->next) printf("%d ", p->data);
    printf("\n");
    while (head) { Node *next = head->next; free(head); head = next; }
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void) {
    char s[] = "([]{})";
    char st[32]; int top = 0, ok = 1;
    for (int i = 0; s[i] && ok; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') st[top++] = c;
        else if (c == ')' || c == ']' || c == '}') {
            if (!top) ok = 0;
            else {
                char o = st[--top];
                if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) ok = 0;
            }
        }
    }
    printf("%s\n", ok && top == 0 ? "balanced" : "not balanced");
    return 0;
}

